/* Eleva member prototype. All product terms, balances and actions are illustrative. */
'use strict';
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const money=(v)=>'₹'+Math.round(v).toLocaleString('en-IN');
const short=(v)=>v>=100000?'₹'+(v/100000).toFixed(2)+'L':money(v);
const esc=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',compass:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM16 8l-2.5 5.5L8 16l2.5-5.5Z',card:'M3 5h18v14H3ZM3 9h18M7 15h3',chart:'M4 20h16M6 16v-5m6 5V4m6 12V8',activity:'M3 12h4l3-8 4 16 3-8h4',arrow:'M5 12h14m-5-5 5 5-5 5',arrowUp:'M7 17 17 7M7 7h10v10',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',plus:'M12 5v14M5 12h14',minus:'M5 12h14',close:'m6 6 12 12M6 18 18 6',lock:'M6 10h12v11H6ZM8 10V7a4 4 0 0 1 8 0v3m-4 5v2',snow:'M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M8 4l4 4 4-4M8 20l4-4 4 4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c-6 7-6 13 0 20 6-7 6-13 0-20',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-10 4a5 5 0 0 1 6 0m-3 4h.01',check:'m5 12 4 4L19 6',shield:'m12 2 8 4v7c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-5',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',gift:'M3 8h18v4H3Zm2 4v9h14v-9M12 8v13m0-13c-8 0-8-7-4-6 3 1 4 6 4 6Zm0 0c8 0 8-7 4-6-3 1-4 6-4 6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM12 11v6m0-10v.01',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2ZM9 7h6M9 11h6M9 15h3',wallet:'M20 7H4V4h15v3M3 7h18v14H3Zm12 5h6v5h-6Z',copy:'M9 8h12v13H9ZM4 16H2V2h13v2',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20ZM9 8a3 3 0 1 1 4 3c-1 0-1 1-1 3m0 3v.01',leaf:'M20 3C8 1 0 11 7 18S23 14 20 3ZM5 21 16 10',logout:'M9 4H3v16h6m4-13 5 5-5 5m-6-5h14'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const mark=()=>'<span class="brand-mark" aria-hidden="true"><img src="./assets/eleva-mark-acid.png" alt=""></span>';
const navs=[['home','home','Overview'],['discover','compass','Discover'],['card','card','My card'],['rewards','spark','Rewards'],['limits','chart','My limits'],['activity','activity','Activity']];
const initial=()=>({version:3,memberStatus:'active',freshAccount:false,rewards:initialRewards(),frozen:false,online:true,international:false,contactless:true,autopay:false,spendCap:100000,outstanding:68450,bill:24850,saved:[],activated:[],waitlist:false,pinSet:false,funds:[{id:'hdfc',name:'HDFC Flexi Cap Fund',type:'Equity · Direct growth',value:500000,pledged:350000},{id:'parag',name:'Parag Parikh Flexi Cap',type:'Equity · Direct growth',value:400000,pledged:250000},{id:'icici',name:'ICICI Prudential Bluechip',type:'Equity · Direct growth',value:300000,pledged:200000}],payments:[],noticesRead:false});
let state;try{state=JSON.parse(localStorage.getItem('eleva-demo-v3'));if(state?.version!==3){state=initial();state.memberStatus='onboarding'}}catch{state=initial();state.memberStatus='onboarding'}
let memberAccess=state.memberStatus!=='onboarding';
ensureRewardsState(state);
let storageAvailable=true;const save=()=>{try{localStorage.setItem('eleva-demo-v3',JSON.stringify(state))}catch{storageAvailable=false}};
let route='home',discoverTab='offers',category='All',query='',activityFilter='All',activityQuery='',returnFocus=null,dialogData=null,toastTimer;
const totals=()=>{const linked=state.funds.reduce((s,f)=>s+f.value,0),pledged=state.funds.reduce((s,f)=>s+f.pledged,0),limit=creditLimitForPledge(pledged);return{linked,pledged,limit,available:limit-state.outstanding,unpledged:linked-pledged,releaseMax:Math.max(0,pledged-minimumPledgeForCredit(state.outstanding))}};
const offers=[
{id:'stay',brand:'THE POSTCARD HOTEL',title:'A little further from ordinary.',benefit:'20% off your next escape',category:'Travel',art:'hotel',description:'Slow mornings. Thoughtful spaces. Make room for a stay that feels different.',terms:['20% off the room rate on a minimum 2-night stay.','Illustrative saving capped at ₹5,000 per booking.','One simulated redemption per member. Valid through 31 Dec 2026.'],code:'ELEVASTAY20'},
{id:'dine',brand:'TABLE FOR TWO',title:'Good taste. Better company.',benefit:'₹1,000 towards your next table',category:'Dining',art:'dining',description:'A seat at a favourite restaurant, and a reason to linger a little longer.',terms:['₹1,000 off a dining bill of ₹4,000 or more.','Reservations required. Alcohol and taxes excluded.','One simulated redemption per member. Valid through 31 Dec 2026.'],code:'ELEVATABLE'},
{id:'work',brand:'BUILT FOR YOUR EVERYDAY',title:'Your next great idea starts here.',benefit:'3 months of a smarter workspace',category:'Work',art:'work',description:'A calmer place to plan, create, and do the work that matters to you.',terms:['Illustrative three-month workspace subscription benefit.','For new subscription accounts only.','Demo activation only; no third-party subscription is created.'],code:'ELEVABUILD'},
{id:'sound',brand:'SOUND & STILLNESS',title:'Turn the world down.',benefit:'15% off premium audio',category:'Lifestyle',art:'sound',description:'Make a little space for your own soundtrack. Thoughtful audio for focused days.',terms:['15% off selected audio products. Maximum saving ₹2,000.','Minimum order ₹5,000. No stacking with other offers.','Illustrative benefit. Valid through 31 Dec 2026.'],code:'ELEVASOUND'},
{id:'wealth',brand:'WEALTH, WITH INTENTION',title:'Give your wealth a fresh perspective.',benefit:'A complimentary portfolio review',category:'Wealth',art:'wealth',description:'Step back, see the bigger picture, and ask better questions about your portfolio.',terms:['One 30-minute introductory review in this concept journey.','No personalised investment advice is provided in this prototype.','Demo activation only. No adviser booking is made.'],code:'ELEVAGROW'},
{id:'weekend',brand:'OFF THE CLOCK',title:'Your weekend, reimagined.',benefit:'Member access to a private preview',category:'Lifestyle',art:'gallery',description:'A quieter corner of the city. An evening of art, conversation, and new perspectives.',terms:['Illustrative member access for two guests.','Event details and availability are placeholders.','Demo activation only. No actual reservation is made.'],code:'ELEVAAFTER'}
];
const baseTx=[{id:'tx1',merchant:'Blue Tokai Coffee',date:'Today, 9:41 AM',category:'Dining',amount:680,letter:'b',color:'#f0ebe2',status:'Settled'},{id:'tx2',merchant:'Apple',date:'25 Oct, 4:18 PM',category:'Lifestyle',amount:14900,letter:'a',color:'#eeeee9',status:'Settled'},{id:'tx3',merchant:'Airbnb',date:'24 Oct, 11:06 AM',category:'Travel',amount:18500,letter:'A',color:'#f9e9e3',status:'Pending'},{id:'tx4',merchant:'Notion',date:'23 Oct, 8:02 PM',category:'Work',amount:1650,letter:'N',color:'#eeeeea',status:'Settled'},{id:'tx5',merchant:'The Grammar Room',date:'22 Oct, 8:36 PM',category:'Dining',amount:4820,letter:'g',color:'#e9eedf',status:'Settled'},{id:'tx6',merchant:'Amazon',date:'21 Oct, 3:28 PM',category:'Lifestyle',amount:7900,letter:'a',color:'#f1ece0',status:'Settled'},{id:'tx7',merchant:'Uber',date:'20 Oct, 9:10 AM',category:'Travel',amount:1200,letter:'U',color:'#e8e8e2',status:'Settled'},{id:'tx8',merchant:'Figma',date:'19 Oct, 2:22 PM',category:'Work',amount:18800,letter:'F',color:'#eee5f4',status:'Settled'}];
const transactions=()=>[...state.payments.map((p,i)=>({id:p.id,merchant:'Payment received',date:p.date,category:'Payments',amount:-p.amount,letter:'↙',color:'#e9f1df',status:'Completed'})),...(state.freshAccount?[]:baseTx)];
const photography={
  hotel:{alt:'A tranquil resort pool surrounded by tropical greenery',position:'55% 55%'},
  dining:{alt:'An intimate restaurant table set with wine glasses and candles',position:'55% 55%'},
  work:{alt:'A modern workspace with a computer and headphones',position:'55% 55%'},
  sound:{alt:'Premium black headphones photographed on a dark surface',position:'55% 55%'},
  wealth:{alt:'A person reviewing finances with a notebook, calculator, and laptop',position:'55% 55%'},
  gallery:{alt:'Visitors exploring paintings in an art gallery',position:'55% 48%'}
};
function art(type){const photo=photography[type]||photography.hotel;return `<img class="benefit-photo photo-${type}" src="./assets/photos/${type}.webp" alt="${photo.alt}" width="1200" height="800" loading="lazy" decoding="async" style="object-position:${photo.position}">`}
function cardPreview(extra=''){return`<div class="card-preview actual-eleva-card ${state.frozen?'frozen':''} ${extra}"><img class="eleva-card-artwork" src="./assets/eleva-card-signature.png" width="870" height="550" alt="Eleva Signature card: brushed black metal, silver Eleva motif, Rahul Singh, and Visa Signature" decoding="async"></div>`}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function navTo(page){if(location.hash.slice(1)===page){route=page;render();window.scrollTo({top:0});}else location.hash=page}
function shell(content){return`<aside class="sidebar"><a class="brand" href="#home" aria-label="Eleva home">${mark()}eleva</a><div class="eyebrow">Your space</div><nav class="nav-list" aria-label="Main navigation">${navs.map(([r,i,l])=>`<a class="nav-item ${route===r?'active':''}" ${route===r?'aria-current="page"':''} href="#${r}">${icon(i)}<span>${l}</span></a>`).join('')}</nav><div class="member-stamp"><div class="mini-line"></div><p>Built for people<br>who build.</p><small>YOUR WEALTH. YOUR CREDIT.</small></div><button class="sidebar-profile" data-action="profile"><span class="avatar">RS</span><span><strong>Rahul Singh</strong><small>Founding member · #001</small></span><span class="arrow">${icon('chevron',15)}</span></button></aside><div class="shell"><header class="topbar"><div class="mobile-logo"><a class="brand" href="#home">${mark()}eleva</a></div><div class="breadcrumb">Your Eleva <span>/ &nbsp;${navs.find(x=>x[0]===route)[2]}</span></div><div class="top-actions"><span class="proto-pill"><i></i>PRIVATE PROTOTYPE · DEMO DATA</span><button class="icon-button" aria-label="Notifications" data-action="notifications">${icon('bell',18)}${!state.noticesRead?'<span class="notification-dot"></span>':''}</button><button class="avatar" aria-label="Your profile" data-action="profile">RS</button></div></header><main id="main" class="main" tabindex="-1">${content}<footer class="app-footer"><span>© 2026 Eleva · Built around your ambition.</span><span>Illustrative terms & demo balances. No real banking actions. &nbsp; <button data-action="about">About this prototype ↗</button></span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navs.filter(n=>n[0]!=='activity').map(([r,i,l])=>`<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}${r==='home'?'Home':r==='card'?'Card':r==='limits'?'Limits':l}</a>`).join('')}</nav>`}
const intro=(label,title,description,extra='')=>`<div class="page-intro"><div>${label?`<div class="welcome-label">${label}</div>`:''}<h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${extra}</div>`;
const sectionTitle=(title,label,action)=>`<div class="section-title"><h2>${title}</h2>${label?`<button class="text-button" data-action="${action}">${label} ${icon('arrow',14)}</button>`:''}</div>`;
const offerCard=(o)=>`<article class="offer-card"><button class="save-button ${state.saved.includes(o.id)?'saved':''}" aria-label="${state.saved.includes(o.id)?'Unsave':'Save'} ${esc(o.brand)} offer" aria-pressed="${state.saved.includes(o.id)}" data-action="save-offer" data-id="${o.id}">${icon('heart',15)}</button><button class="offer-art-button" data-action="offer" data-id="${o.id}" aria-label="Explore ${esc(o.brand)} offer"><div class="offer-art"><span class="offer-top">${o.category} / Eleva privileges</span>${art(o.art)}<span class="offer-tag">${state.activated.includes(o.id)?'✓ Activated':o.benefit}</span></div></button><div class="offer-info"><div class="offer-brand">${o.brand}</div><h3>${o.title}</h3><p>${o.benefit}</p><button class="text-button" data-action="offer" data-id="${o.id}">${state.activated.includes(o.id)?'View benefit':'Explore benefit'} ${icon('arrow',13)}</button></div></article>`;
function txRow(t){return`<button class="transaction" data-action="transaction" data-id="${t.id}"><span class="merchant-icon" style="background:${t.color}">${t.letter}</span><span class="merchant-text"><strong>${t.merchant}</strong><small>${t.date}${t.status==='Pending'?' · Pending':''}</small></span>${route==='activity'?`<span class="category">${t.category}</span>`:''}<span class="amount ${t.amount<0?'credit':''}">${t.amount<0?'+':'−'}${money(Math.abs(t.amount))}<small>${t.amount<0?'Payment':'Eleva • 2026'}</small></span></button>`}
function home(){const t=totals();return intro('MAKE ROOM FOR WHAT’S NEXT','Good morning, <em>Rahul.</em>','Everyday spending. Something more for your future.','<button class="secondary-button" data-action="onboard-start">Try onboarding '+icon('arrow',14)+'</button>')+onboardingWelcome()+`<div class="dashboard-grid"><section class="hero-panel"><div><div class="eyebrow">${icon('wallet',13)} Available to spend</div><div class="big-money">${money(t.available)}</div><div class="small-sub">of your <strong>${money(t.limit)}</strong> wealth-backed limit</div><div class="balance-meter"><span style="width:${(t.limit?state.outstanding/t.limit*100:0)}%"></span></div><div class="meter-labels"><span>${money(state.outstanding)} used</span><strong>${(t.limit?Math.round(t.available/t.limit*100):0)}% available</strong></div><button class="text-button" data-action="go-limits">Understand your limit ${icon('arrow',14)}</button></div><button class="hero-card-wrap" data-action="go-card" aria-label="Open your Eleva card">${cardPreview()}</button><span class="card-caption">${state.frozen?'CARD FROZEN':'YOUR ELEVA SIGNATURE'} · • 2026</span></section>${rewardHomeHero()}</div><div class="quick-actions"><button class="quick-action" data-action="pay">${icon('wallet')}Pay card bill</button><button class="quick-action" data-action="freeze">${icon('snow')}${state.frozen?'Unfreeze card':'Freeze card'}</button><button class="quick-action" data-action="pledge">${icon('plus')}Increase limit</button><button class="quick-action" data-action="go-discover">${icon('gift')}Member benefits</button></div>${sectionTitle('A little more, for you.','Discover all','go-discover')}<div class="offer-grid home-offers">${offers.slice(0,3).map(offerCard).join('')}</div><div class="home-bottom"><section class="panel activity-panel">${sectionTitle('Recent activity','View all','go-activity')}${transactions().length?transactions().slice(0,3).map(txRow).join(''):'<p class="new-account-empty">Your story starts here. Your card transactions will appear here.</p>'}</section><div class="stack"><section class="panel"><div class="spread"><span class="small muted">Your next payment</span><span class="tag">${state.bill===0?'Paid':'Due 05 Nov'}</span></div><div class="bill-amount">${money(state.bill)}</div><p class="small muted">${state.bill===0?'You’re all caught up. Nicely done.':'Statement issued 06 Oct · due 05 Nov'}</p><button class="text-button" data-action="pay">${state.bill===0?'Manage payments':'Pay your bill'} ${icon('arrow',14)}</button></section><div class="insight-strip"><div class="insight-icon">${icon('spark',24)}</div><div><h4>${rewardCurrency(rewardSummary().investedPaise)} invested from rewards.</h4><p>Small moves, adding up. Explore your investment story.</p><button class="text-button" data-action="go-rewards">Your rewards ${icon('arrow',13)}</button></div></div></div></div>`}
function discover(){return intro('CURATED FOR YOUR EVERYDAY','Good things. <em style="font-family:Georgia,serif">Great privileges.</em>','A collection of benefits for the life you’re building.')+`<div class="tabs" role="tablist" aria-label="Discover sections">${[['offers','Member benefits'],['products','Products'],['saved','Saved',state.saved.length]].map(([v,l,n])=>`<button role="tab" aria-selected="${discoverTab===v}" class="${discoverTab===v?'active':''}" data-action="discover-tab" data-id="${v}">${l}${n?' ('+n+')':''}</button>`).join('')}</div>${discoverTab==='products'?products():`<div class="discover-banner"><div><div class="eyebrow">The Eleva edit / October</div><h2>For the way<br>you choose to live.</h2><p>Work a little smarter. Step out a little further.</p></div><div class="banner-photo">${art('gallery')}</div></div><div class="discover-toolbar"><div class="filters">${['All','Travel','Dining','Work','Lifestyle','Wealth'].map(c=>`<button class="filter ${category===c?'active':''}" data-action="category" data-id="${c}">${c}</button>`).join('')}</div><label class="search-field">${icon('search')}<input aria-label="Search benefits" id="offer-search" value="${esc(query)}" placeholder="Find your next good thing"></label></div><div id="offer-results">${offerResults()}</div>`}`}
function offerResults(){const items=offers.filter(o=>(discoverTab!=='saved'||state.saved.includes(o.id))&&(category==='All'||o.category===category)&&(o.title+' '+o.brand+' '+o.benefit).toLowerCase().includes(query.toLowerCase()));return `<div class="result-count">${items.length} ${items.length===1?'benefit':'benefits'} ${discoverTab==='saved'?'saved for you':'to explore'} · Illustrative offers</div><div class="offer-grid discover-offers">${items.length?items.map(offerCard).join(''):`<div class="empty">${icon(discoverTab==='saved'?'heart':'search',30)}<h3>${discoverTab==='saved'?'Keep your favourites close.':'No benefits found.'}</h3><p>${discoverTab==='saved'?'Tap the heart on any benefit to save it here.':'Try another search or explore a different category.'}</p><button class="secondary-button" data-action="clear-discover">Explore all benefits</button></div>`}</div>`}
function products(){return`<div class="product-grid"><article class="product-card"><div class="product-art">${cardPreview()}</div><div class="product-body"><span class="tag">Your current card</span><h2>Eleva Signature</h2><p class="lead">Your wealth opens doors. A premium card that recognises the life you’re building.</p><ul><li>Wealth-backed spending power</li><li>Curated travel, dining, and work benefits</li><li>Simple controls. Everything in your hands.</li></ul><button class="primary-button full" data-action="go-card">Manage your card ${icon('arrow',16)}</button></div></article><article class="product-card"><div class="product-art photo-product">${art('wealth')}</div><div class="product-body"><span class="tag" style="background:#f0e9f7;color:#967da8">Part of your Eleva</span><h2>Rewards, meet investments.</h2><p class="lead">Turn available points into investments. Choose your destination once, then convert with one click.</p><ul><li>One-time investment destination setup</li><li>Single-click reward conversion</li><li>Clear order and unit-allotment tracking</li></ul><button class="primary-button full" data-action="go-rewards">Explore reward investing ${icon('arrow',16)}</button></div></article></div><p class="prototype-footnote">Product names, eligibility, pricing, and benefits shown are illustrative and subject to an eventual issuing partner’s terms.</p>`}
function controls(){return`<div class="control-row"><div class="control-label">${icon('globe')}<div><strong>Online payments</strong><small>Websites, apps, and subscriptions</small></div></div>${toggle('online','Online payments')}</div><div class="control-row"><div class="control-label">${icon('globe')}<div><strong>International payments</strong><small>Spends outside India</small></div></div>${toggle('international','International payments')}</div><div class="control-row"><div class="control-label">${icon('wifi')}<div><strong>Contactless payments</strong><small>Tap and pay at a terminal</small></div></div>${toggle('contactless','Contactless payments')}</div><button class="control-row full" data-action="spend-cap"><div class="control-label">${icon('settings')}<div style="text-align:left"><strong>Per-transaction cap</strong><small>${money(state.spendCap)} · within your available limit</small></div></div>${icon('chevron',17)}</button>`}
const toggle=(key,label)=>`<button class="switch" role="switch" aria-checked="${state[key]}" aria-label="${label}" data-action="toggle" data-id="${key}"></button>`;
function cardPage(){const t=totals();return intro('YOUR EVERYDAY, ELEVATED','A card that gets you.','A little control goes a long way.')+`<div class="two-col"><div class="stack"><section class="panel"><div class="section-head"><h3>Eleva Signature</h3><span class="pill ${state.frozen?'':'live'}"><i class="status-dot"></i>${state.frozen?'Frozen':'Active'} · • 2026</span></div><div class="card-stage">${cardPreview()}<span class="pill">${icon('shield',12)} Wealth-backed. Built for you.</span></div><div class="card-actions"><button data-action="details">${icon('eye') }View details</button><button data-action="freeze">${icon('snow')}${state.frozen?'Unfreeze':'Freeze card'}</button><button data-action="pin">${icon('lock')}Change PIN</button></div>${state.frozen?'<div class="spacer"></div><div class="callout warning">'+icon('snow',17)+'Your card is frozen in this demo. New card payments are paused until you unfreeze it. Bill payments remain available.</div>':''}<div class="spacer"></div><div class="data-row"><span>Cardholder</span><strong>Rahul Singh</strong></div><div class="data-row"><span>Available to spend</span><strong>${money(t.available)}</strong></div><div class="data-row"><span>Member number</span><strong>Founding 500 · #001</strong></div></section></div><div class="stack"><section class="panel"><div class="spread"><h3>Stay on top of your dues.</h3>${icon('receipt',18)}</div><div class="bill-amount">${money(state.bill)}</div><div class="spread small muted"><span>Statement balance</span><span>Due 05 Nov 2026</span></div><div class="spacer"></div><button class="primary-button full" data-action="pay">${state.bill?'Pay card bill':'Manage payments'} ${icon('arrow',16)}</button><div class="control-row"><div class="control-label"><div><strong>Autopay</strong><small>${state.autopay?'Demo mandate enabled · no real debit':'One less thing on your mind'}</small></div></div><button class="switch" role="switch" aria-checked="${state.autopay}" aria-label="Autopay" data-action="autopay"></button></div></section><section class="panel"><h3>Make it work your way.</h3><div class="space-12"></div>${controls()}</section><button class="panel spread full" data-action="statement"><div class="row">${icon('download',20)}<span style="text-align:left"><h4>Statements & documents</h4><p class="small muted" style="margin-top:6px">Your October demo statement</p></span></div>${icon('chevron',17)}</button><button class="panel spread full" data-action="go-activity"><div class="row">${icon('activity',20)}<span style="text-align:left"><h4>Transactions & payments</h4><p class="small muted" style="margin-top:6px">See your card activity</p></span></div>${icon('chevron',17)}</button></div></div>`}
function limits(){const t=totals();return intro('YOUR WEALTH. YOUR CREDIT.','See your room to move.','Understand where your limit comes from, and how to grow it.')+`<div class="two-col"><div class="stack"><section class="panel limit-hero"><div class="spread"><span class="eyebrow" style="color:#84946f">Available to spend</span><span class="tag">${icon('shield',11)} Healthy backing</span></div><div class="big-money">${money(t.available)}</div><div class="balance-meter"><span style="width:${(t.limit?state.outstanding/t.limit*100:0)}%"></span></div><div class="limit-stats"><div><small>Total approved limit</small><strong>${money(t.limit)}</strong></div><div><small>Outstanding balance</small><strong>${money(state.outstanding)}</strong></div></div><div class="limit-buttons"><button class="primary-button dark-button" data-action="pledge">${icon('plus',16)}Increase limit</button><button class="secondary-button" data-action="pay">Pay & free up limit</button></div></section><section class="panel"><h3>Here’s how it adds up.</h3><div class="formula"><div><strong>${short(t.pledged)}</strong><small>Pledged investments</small></div><span>×</span><div><strong>55%</strong><small>Illustrative advance rate</small></div><span>=</span><div><strong>${short(t.limit)}</strong><small>Credit limit</small></div></div><div class="callout">${icon('info',17)}<span>Your investments stay invested while backing your card. Your available limit is the credit limit minus your outstanding balance.</span></div><p class="amount-note">The 55% advance is rounded up to the next ₹1,000. Portfolio values can move. A fall in pledged value may reduce your limit and require a top-up or repayment. Rates and eligible funds would depend on the issuing partner.</p><button class="text-button" data-action="stress">Explore a market change ${icon('arrow',14)}</button></section></div><div class="stack"><section class="panel"><div class="section-head"><h3>Your linked portfolio</h3><span class="tag">${state.funds.length} funds</span></div><div class="spread"><div><p class="small muted">Total current value</p><div class="wealth-value">${money(t.linked)}</div></div><div style="text-align:right"><p class="small muted">Not pledged</p><p style="margin-top:8px;font-size:18px">${money(t.unpledged)}</p></div></div>${state.funds.map(f=>`<div class="fund-row"><div class="spread"><div class="row"><span class="fund-icon">${f.name[0]}</span><div><strong>${f.name}</strong><small>${f.type}</small></div></div><div><strong>${short(f.value)}</strong><small>${short(f.pledged)} pledged</small></div></div><div class="fund-meter"><span style="width:${f.pledged/f.value*100}%"></span></div></div>`).join('')}<div class="spread" style="margin-top:12px"><button class="text-button" data-action="pledge">Pledge more ${icon('plus',14)}</button><button class="text-button" data-action="release">Release investments ${icon('arrow',14)}</button></div></section><div class="callout purple">${icon('leaf',22)}<span>Wealth backs your limit. Repayments restore it. Pledging an extra ₹1,00,000 adds ₹55,000 of limit in this demo.</span></div></div></div>`}
function activity(){return intro('THE DETAILS, ALL HERE','Every move, in view.','A clear picture of your spending and payments.',`<button class="secondary-button" data-action="statement">${icon('download',14)}Statement</button>`)+`<div class="stat-row"><div class="stat-card"><small>Current outstanding</small><strong>${money(state.outstanding)}</strong><p>Includes unbilled & pending spends</p></div><div class="stat-card"><small>Payment due</small><strong>${money(state.bill)}</strong><p>${state.bill?'Due by 05 November':'Statement balance paid'}</p></div><div class="stat-card"><small>Benefits activated</small><strong>${String(state.activated.length).padStart(2,'0')}</strong><p>Your member privileges</p></div></div><div class="activity-header"><div class="filters">${['All','Spends','Payments','Pending'].map(f=>`<button class="filter ${activityFilter===f?'active':''}" data-action="activity-filter" data-id="${f}">${f}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="activity-search" aria-label="Search transactions" value="${esc(activityQuery)}" placeholder="Search transactions"></label></div><section id="transaction-results" class="panel activity-table">${activityResults()}</section>`}
function activityResults(){const list=transactions().filter(t=>(activityFilter==='All'||activityFilter==='Spends'&&t.amount>0||activityFilter==='Payments'&&t.amount<0||activityFilter==='Pending'&&t.status==='Pending')&&(t.merchant+' '+t.category).toLowerCase().includes(activityQuery.toLowerCase()));return list.length?list.map(txRow).join(''):'<p class="no-results">No transactions here yet. Try another filter or search.</p>'}
function render(){if(window.elevaRender){window.elevaRender();return}if(route==='onboarding'){$('#app').innerHTML=onboardingPage();document.title='Eleva — Get started';return}const content={home,discover,card:cardPage,rewards:rewardsPage,limits,activity}[route]();$('#app').innerHTML=shell(content);document.title='Eleva — '+navs.find(n=>n[0]===route)[2]}
function openDialog(title,body,actions=''){if(!$('#overlay-root').firstChild)returnFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><header class="drawer-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close',17)}</button></header><div class="drawer-body">${body}</div><div class="drawer-actions">${actions}</div></section></div>`;document.body.style.overflow='hidden';$('#app').inert=true;$('.drawer').focus();}
function closeDialog(){const focus=returnFocus;$('#overlay-root').innerHTML='';document.body.style.overflow='';$('#app').inert=false;dialogData=null;if(focus?.isConnected)focus.focus();else $('#main').focus();returnFocus=null}
function offerDialog(id){const o=offers.find(o=>o.id===id);if(!o)return;const active=state.activated.includes(id);openDialog('Your member privilege',`<div class="modal-image"><div class="offer-art">${art(o.art)}</div></div><div class="eyebrow">${o.brand} · ${o.category}</div><h3>${o.title}</h3><p class="lead">${o.description}</p><div class="callout">${icon('gift',20)}<strong>${o.benefit}</strong></div>${active?`<div class="code-box">${o.code}</div><p class="small muted">Your demo benefit is activated. This code is illustrative and cannot be used with a merchant.</p>`:''}<hr class="divider"><h4>The finer details</h4><ul>${o.terms.map(t=>`<li>${t}</li>`).join('')}</ul>`,active?`<button class="primary-button" data-action="copy-code" data-id="${id}">${icon('copy',16)}Copy demo code</button><button class="secondary-button" data-action="close">Done</button>`:`<button class="primary-button" data-action="activate-offer" data-id="${id}">Activate demo benefit ${icon('arrow',16)}</button><span class="small">Illustrative offer · no real booking or purchase</span>`)}
function paymentDialog(){if(state.outstanding===0){openDialog('All caught up.',`<div class="success"><div class="success-icon">${icon('check',30)}</div><h3>Nothing to pay.</h3><p>Your outstanding balance is zero. Every rupee of your limit is available again.</p></div>`,`<button class="primary-button" data-action="close">Back to your day</button>`);return}dialogData={type:'payment',amount:state.bill||state.outstanding};openDialog('Pay your card bill',`<div class="eyebrow">ELEVA SIGNATURE · • 2026</div><h3>A fresh start for your limit.</h3><p class="lead">Every repayment restores the same amount of available spending power.</p><label class="radio-option"><input type="radio" name="pay-choice" value="statement" ${state.bill?'checked':''} ${state.bill?'':'disabled'}><span><strong>Statement balance</strong><small>Due 05 Nov 2026</small></span><strong>${money(state.bill)}</strong></label><label class="radio-option"><input type="radio" name="pay-choice" value="full" ${state.bill?'':'checked'}><span><strong>Total outstanding</strong><small>Clear billed and unbilled spends</small></span><strong>${money(state.outstanding)}</strong></label><label class="radio-option"><input type="radio" name="pay-choice" value="custom"><span><strong>Another amount</strong><small>Choose how much to repay</small></span></label><div id="custom-pay-wrap" hidden><label class="form-label" for="pay-amount">Amount in rupees</label><input class="input amount-input" id="pay-amount" type="number" min="1" max="${state.outstanding}" step="1" inputmode="numeric" placeholder="Enter an amount"><p class="error-text" id="pay-error" role="status"></p></div><div class="panel"><div class="data-row"><span>Paying from</span><strong>Demo savings account • 4821</strong></div><div class="data-row"><span>Payment method</span><strong>Simulated bank transfer</strong></div></div><div class="callout">${icon('shield',17)}No money moves. The prototype updates your demo balance immediately.</div>`,`<button class="primary-button" data-action="review-payment">Review payment ${icon('arrow',16)}</button>`);dialogData={type:'payment'}}
function reviewPayment(){const choice=$('input[name="pay-choice"]:checked')?.value;const amount=choice==='statement'?state.bill:choice==='full'?state.outstanding:Number($('#pay-amount').value);if(!Number.isFinite(amount)||amount<1||amount>state.outstanding){$('#pay-error').textContent=`Enter an amount from ₹1 to ${money(state.outstanding)}.`;$('#pay-amount').classList.add('form-error');return}const t=totals();dialogData={type:'payment-review',amount};openDialog('Review your payment',`<div class="eyebrow">SIMULATED PAYMENT</div><h3>Ready for a little more room?</h3><div class="bill-amount">${money(amount)}</div><p class="lead">This will be credited to your Eleva card.</p><div class="receipt"><div class="data-row"><span>From</span><strong>Demo savings • 4821</strong></div><div class="data-row"><span>To</span><strong>Eleva Signature • 2026</strong></div><div class="data-row"><span>Outstanding after payment</span><strong>${money(state.outstanding-amount)}</strong></div><div class="data-row"><span>Available after payment</span><strong>${money(t.available+amount)}</strong></div></div><p class="amount-note">No funds will be debited. This is a prototype interaction.</p>`,`<button class="primary-button" data-action="confirm-payment">Confirm demo payment · ${money(amount)}</button><button class="secondary-button" data-action="pay">Change amount</button>`)}
function confirmPayment(){if(dialogData?.type!=='payment-review')return;const amount=dialogData.amount;state.outstanding=Math.max(0,state.outstanding-amount);state.bill=Math.max(0,state.bill-amount);const id='pay-'+Date.now();state.payments.unshift({id,amount,date:'Just now · Demo payment'});save();render();dialogData={type:'receipt',id};openDialog('Payment complete',`<div class="success"><div class="success-icon">${icon('check',30)}</div><h3>Room, restored.</h3><p>Your demo card payment was successful.</p><div class="big-money">${money(amount)}</div><p>Available to spend is now ${money(totals().available)}.</p></div><div class="receipt"><div class="data-row"><span>Reference</span><strong>ELV-${String(state.payments.length).padStart(4,'0')}</strong></div><div class="data-row"><span>Status</span><strong>Completed · Demo</strong></div><div class="data-row"><span>Statement balance remaining</span><strong>${money(state.bill)}</strong></div></div>`,`<button class="primary-button" data-action="finish-payment">View payment activity ${icon('arrow',16)}</button><button class="secondary-button" data-action="close">Done</button>`)}
function pledgeDialog(){const t=totals();if(!t.unpledged){openDialog('Your portfolio is fully pledged',`<p class="lead">All linked investments are already backing your card. You can repay outstanding dues to restore available spending power.</p>`,`<button class="primary-button" data-action="pay">Pay & free up limit</button>`);return}openDialog('Give your limit more room.',`<div class="eyebrow">PLEDGE MORE · KEEP IT INVESTED</div><p class="lead">Choose an amount from your unpledged investments. This demo uses a 55% advance rate, with the total limit rounded up to ₹1,000.</p>${state.funds.map(f=>`<div class="allocation-row"><div class="spread"><div><strong>${f.name}</strong><small>${money(f.value-f.pledged)} available to pledge</small></div><input class="pledge-amount" aria-label="Pledge amount for ${f.name}" data-fund="${f.id}" type="number" min="0" max="${f.value-f.pledged}" step="1" value="0" inputmode="numeric"></div></div>`).join('')}<p class="error-text" id="pledge-error" role="status"></p><div class="panel"><div class="data-row"><span>Additional pledge</span><strong id="pledge-total">₹0</strong></div><div class="data-row"><span>Added credit limit · after rounding</span><strong id="pledge-credit">₹0</strong></div><div class="data-row"><span>New total credit limit</span><strong id="pledge-new">${money(t.limit)}</strong></div></div><label class="check-label"><input id="pledge-consent" type="checkbox"><span>I understand these investments are marked as pledged in this demo. Pledged value can move with the market; a real pledge would require lender approval and separate authorisation.</span></label>`,`<button class="primary-button" data-action="review-pledge" id="review-pledge" disabled>Review limit increase ${icon('arrow',16)}</button>`)}
function pledgeValues(){return $$('.pledge-amount').map(el=>({id:el.dataset.fund,amount:Number(el.value),max:Number(el.max)}))}
function updatePledge(){const values=pledgeValues(),valid=values.every(v=>Number.isFinite(v.amount)&&v.amount>=0&&v.amount<=v.max&&Number.isInteger(v.amount));const amount=values.reduce((s,v)=>s+v.amount,0);$('#pledge-error').textContent=valid?'':'Use whole rupees within the available amount for each fund.';$('#pledge-total').textContent=money(amount);$('#pledge-credit').textContent=money((creditLimitForPledge(totals().pledged+amount)-totals().limit));$('#pledge-new').textContent=money(creditLimitForPledge(totals().pledged+amount));$('#review-pledge').disabled=!(valid&&amount>=1&&$('#pledge-consent').checked)}
function reviewPledge(){const allocations=pledgeValues();if(allocations.some(v=>v.amount<0||v.amount>v.max)||!$('#pledge-consent').checked)return;const amount=allocations.reduce((s,v)=>s+v.amount,0);if(amount<1)return;dialogData={type:'pledge',allocations,amount};const t=totals(),nextLimit=creditLimitForPledge(t.pledged+amount);openDialog('Review your limit increase',`<div class="eyebrow">YOUR INVESTMENTS, STILL INVESTED</div><h3>More backing. More possibility.</h3><div class="panel">${allocations.filter(a=>a.amount>0).map(a=>`<div class="data-row"><span>${state.funds.find(f=>f.id===a.id).name}</span><strong>${money(a.amount)}</strong></div>`).join('')}<div class="data-row"><span>Additional pledge</span><strong>${money(amount)}</strong></div></div><div class="receipt"><div class="data-row"><span>Current credit limit</span><strong>${money(t.limit)}</strong></div><div class="data-row"><span>New credit limit</span><strong>${money(nextLimit)}</strong></div><div class="data-row"><span>New available limit</span><strong>${money(nextLimit-state.outstanding)}</strong></div></div><p class="amount-note">This changes demo balances only. Your real investments are untouched.</p>`,`<button class="primary-button" data-action="confirm-pledge">Confirm demo pledge ${icon('check',17)}</button><button class="secondary-button" data-action="pledge">Edit amounts</button>`)}
function confirmPledge(){if(dialogData?.type!=='pledge')return;const {allocations,amount}=dialogData;for(const a of allocations){const fund=state.funds.find(f=>f.id===a.id);fund.pledged+=a.amount}save();render();const t=totals();dialogData=null;openDialog('Your limit just grew.',`<div class="success"><div class="success-icon">${icon('chart',29)}</div><h3>A little more possibility.</h3><p>${money(amount)} in additional investments now backs your demo card.</p><div class="big-money">${money(t.available)}</div><p>Available to spend<br>Total credit limit ${money(t.limit)}</p></div><div class="callout">${icon('leaf',19)}Your investment units stay invested. A pledge earmarks them as security for the card.</div>`,`<button class="primary-button" data-action="finish-limit">See updated limits ${icon('arrow',16)}</button>`)}
function releaseDialog(){const t=totals();openDialog('Release pledged investments',`<div class="eyebrow">KEEP YOUR BACKING IN BALANCE</div><h3>Make room in your portfolio.</h3><p class="lead">Releasing a pledge reduces your credit limit. Your remaining limit must cover the full outstanding balance.</p><div class="receipt"><div class="data-row"><span>Pledged now</span><strong>${money(t.pledged)}</strong></div><div class="data-row"><span>Maximum releasable in this model</span><strong>${money(t.releaseMax)}</strong></div></div><label class="form-label" for="release-amount">Amount to release in rupees</label><input class="input amount-input" id="release-amount" type="number" min="1" max="${t.releaseMax}" step="1" placeholder="e.g. 50000" inputmode="numeric"><p class="error-text" id="release-error" role="status"></p><div class="callout">${icon('info',17)}Demo allocation is released across funds, starting with the first pledged fund. No real investment instruction is sent.</div>`,`<button class="primary-button" data-action="review-release">Review release ${icon('arrow',16)}</button>`)}
function reviewRelease(){const amount=Number($('#release-amount').value),t=totals();if(!Number.isInteger(amount)||amount<1||amount>t.releaseMax){$('#release-error').textContent=`Enter whole rupees from ₹1 to ${money(t.releaseMax)}.`;return}dialogData={type:'release',amount};const next=creditLimitForPledge(t.pledged-amount);openDialog('Review pledge release',`<h3>A smaller pledge. A smaller limit.</h3><p class="lead">Your outstanding stays the same. Your spending power changes.</p><div class="receipt"><div class="data-row"><span>Investments to release</span><strong>${money(amount)}</strong></div><div class="data-row"><span>New credit limit</span><strong>${money(next)}</strong></div><div class="data-row"><span>Outstanding balance</span><strong>${money(state.outstanding)}</strong></div><div class="data-row"><span>Available after release</span><strong>${money(next-state.outstanding)}</strong></div></div><p class="amount-note">A real release would require lender approval. This action only updates demo data.</p>`,`<button class="primary-button" data-action="confirm-release">Confirm demo release</button><button class="secondary-button" data-action="release">Change amount</button>`)}
function confirmRelease(){if(dialogData?.type!=='release')return;let left=dialogData.amount;for(const f of state.funds){const amount=Math.min(f.pledged,left);f.pledged-=amount;left-=amount}state.spendCap=Math.min(state.spendCap,totals().limit);save();render();dialogData=null;openDialog('Investments released',`<div class="success"><div class="success-icon">${icon('check',30)}</div><h3>Back in your hands.</h3><p>The demo pledge has been released. Your updated credit limit is ${money(totals().limit)}.</p><div class="big-money">${money(totals().available)}</div><p>Available to spend</p></div>`,`<button class="primary-button" data-action="finish-limit">View updated limits</button>`)}
function stressDialog(){openDialog('What if the market moves?',`<div class="eyebrow">ILLUSTRATIVE LIMIT SIMULATOR</div><h3>See the relationship, clearly.</h3><p class="lead">Adjust the market change to see how your pledged value and credit limit could move. Your saved balances will stay the same.</p><div class="spread"><label class="form-label" for="market-range">Change in pledged portfolio value</label><strong id="market-value">0%</strong></div><input class="range" id="market-range" aria-label="Market change percentage" type="range" min="-60" max="20" step="1" value="0"><div class="spread small muted"><span>−60%</span><span>+20%</span></div><div class="panel" id="stress-results"></div><div class="callout warning">${icon('info',18)}If a reduced limit no longer covers outstanding dues, the model requires additional backing or a repayment. Real thresholds, timelines, and actions would follow the lender’s terms.</div>`,`<button class="primary-button" data-action="close">Back to my limits</button>`);updateStress()}
function updateStress(){const pct=Number($('#market-range').value),t=totals(),pledged=Math.round(t.pledged*(1+pct/100)),limit=creditLimitForPledge(pledged),available=limit-state.outstanding;$('#market-value').textContent=(pct>0?'+':'')+pct+'%';$('#stress-results').innerHTML=`<div class="data-row"><span>Simulated pledged value</span><strong>${money(pledged)}</strong></div><div class="data-row"><span>Simulated credit limit</span><strong>${money(limit)}</strong></div><div class="data-row"><span>${available<0?'Repayment needed to cover shortfall':'Simulated available limit'}</span><strong style="color:${available<0?'#aa6146':'#658947'}">${money(Math.abs(available))}</strong></div><p class="amount-note" style="margin-bottom:0">${available<0?'Illustrative shortfall: repay this amount or add sufficient eligible collateral.':'Your outstanding remains covered in this scenario.'}</p>`}
function spendCapDialog(){const t=totals();openDialog('Your per-transaction cap',`<h3>Set your comfort zone.</h3><p class="lead">A personal control for each card transaction. It never increases the amount available on your card.</p><div class="summary-heading">Current cap</div><div class="range-summary" id="cap-value">${money(Math.min(state.spendCap,t.limit))}</div><input type="range" class="range" id="cap-range" aria-label="Per-transaction spending cap" min="0" max="${t.limit}" step="1" value="${Math.min(state.spendCap,t.limit)}"><div class="spread small muted"><span>₹0</span><span>${money(t.limit)}</span></div><div class="spacer"></div><div class="callout">${icon('info',17)}The effective amount you can spend is the lower of your cap and available limit. A ₹0 cap blocks all new card spends in this demo.</div>`,`<button class="primary-button" data-action="save-cap">Save cap</button>`)}
function transactionDialog(id){const t=transactions().find(t=>t.id===id);if(!t)return;openDialog(t.amount<0?'Payment details':'Transaction details',`<div class="success" style="padding-bottom:0"><span class="merchant-icon" style="background:${t.color};width:62px;height:62px;font-size:25px;margin:0 auto 22px">${t.letter}</span><h3>${t.merchant}</h3><div class="big-money">${t.amount<0?'+':'−'}${money(Math.abs(t.amount))}</div><p>${t.date}</p></div><div class="panel"><div class="data-row"><span>Status</span><strong>${t.status}</strong></div><div class="data-row"><span>Category</span><strong>${t.category}</strong></div><div class="data-row"><span>Card</span><strong>Eleva Signature • 2026</strong></div><div class="data-row"><span>Reference</span><strong>${t.amount<0?'Demo payment':id.toUpperCase()+'-ELV-2026'}</strong></div></div>${t.status==='Pending'?'<div class="callout">'+icon('info',17)+'Pending authorisations already reduce your available limit. The final settled amount may change.</div>':'<p class="small muted">This is an illustrative transaction from the demo dataset.</p>'}`,`<button class="primary-button" data-action="close">Done</button>${t.amount>0?'<button class="secondary-button" data-action="transaction-help">Get help with this transaction</button>':''}`)}
function notifications(){state.noticesRead=true;save();render();openDialog('Your latest',`<div class="eyebrow">A LITTLE HEADS-UP</div><div class="notice">${icon('wallet',20)}<div><strong>${state.bill?'Your next payment is coming up.':'Your statement is paid.'}</strong><small>${state.bill?money(state.bill)+' is due on 05 Nov. A repayment restores your available limit.':'Nothing due on your current statement. Check your outstanding for unbilled transactions.'}</small><br><button class="text-button" data-action="pay">${state.bill?'Pay card bill':'View payment options'} ${icon('arrow',13)}</button></div></div><div class="notice">${icon('gift',20)}<div><strong>The October edit has arrived.</strong><small>Stays, good tables, and tools for your next great idea.</small><br><button class="text-button" data-action="close-discover">Explore your benefits ${icon('arrow',13)}</button></div></div><div class="notice">${icon('shield',20)}<div><strong>Your wealth backs your next move.</strong><small>${money(totals().pledged)} in demo pledged investments supports a ${money(totals().limit)} credit limit.</small><br><button class="text-button" data-action="finish-limit">Understand your limit ${icon('arrow',13)}</button></div></div>`)}
function profile(){openDialog('Your Eleva',`<div class="member-card"><div class="spread"><span class="eyebrow">Founding member</span>${mark()}</div><h3>Rahul Singh</h3><p>Independent by choice.<br>Building what comes next.</p><div class="spacer"></div><span class="pill">PRIVATE MEMBER · #001 / 500</span></div><div class="data-row"><span>Account</span><strong>Demo member profile</strong></div><div class="data-row"><span>Card</span><strong>Eleva Signature</strong></div><button class="settings-row row" data-action="notifications">${icon('bell',19)}<span><strong>Notifications</strong><small>Payments, benefits, and portfolio updates</small></span>${icon('chevron',16)}</button><button class="settings-row row" data-action="help">${icon('help',19)}<span><strong>Here to help</strong><small>Understand the prototype</small></span>${icon('chevron',16)}</button><button class="settings-row row" data-action="onboard-start">${icon('card',19)}<span><strong>Try onboarding</strong><small>Phone, portfolio, pledge and card unlock</small></span>${icon('chevron',16)}</button><button class="settings-row row" data-action="reset-ask">${icon('activity',19)}<span><strong>Reset demo</strong><small>Restore the starting balances and preferences</small></span>${icon('chevron',16)}</button><p class="prototype-footnote">Demo changes are saved only in this browser. ${storageAvailable?'Onboarding identifiers stay in memory for the current setup only. No details are sent to a bank or stored with this member profile.':'Browser storage is unavailable, so changes last for this session only.'}</p>`)}
function statementDialog(){openDialog('Your statement',`<div class="eyebrow">OCTOBER 2026 · DEMO STATEMENT</div><h3>A clear picture of the month.</h3><div class="panel"><div class="data-row"><span>Card</span><strong>Eleva Signature • 2026</strong></div><div class="data-row"><span>Statement generated</span><strong>06 Oct 2026</strong></div><div class="data-row"><span>Original amount due</span><strong>${state.freshAccount?'₹0':'₹24,850'}</strong></div><div class="data-row"><span>Statement balance remaining</span><strong>${money(state.bill)}</strong></div><div class="data-row"><span>Payment due</span><strong>05 Nov 2026</strong></div><div class="data-row"><span>Current total outstanding</span><strong>${money(state.outstanding)}</strong></div></div><p class="lead">Export the demo activity as a CSV to inspect the transactions behind this prototype.</p><p class="prototype-footnote">${state.freshAccount?'This new demo card has no transactions or statement dues.':'The opening statement balance is ₹24,850. Newer sample transactions appear in current outstanding.'} The CSV is demo data, not an official account statement.</p>`,`<button class="primary-button" data-action="export">${icon('download',16)}Download demo activity CSV</button><button class="secondary-button" data-action="pay">Pay card bill</button>`)}
function exportActivity(){const rows=[['Eleva prototype — demo data only'],['Merchant','Date','Category','Amount INR (debit positive)','Status'],...transactions().map(t=>[t.merchant,t.date,t.category,t.amount,t.status])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='Eleva-demo-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo activity downloaded.')}
function pinDialog(){openDialog('Set a demo card PIN',`<h3>A little extra peace of mind.</h3><p class="lead">Use a made-up four-digit PIN to try this flow. It is validated locally, then discarded. Do not enter your real PIN.</p><form id="pin-form" autocomplete="off"><label class="form-label" for="pin-new">New demo PIN · 4 digits</label><input type="password" id="pin-new" class="input" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" autocomplete="new-password"><label class="form-label" for="pin-confirm">Confirm demo PIN</label><input type="password" id="pin-confirm" class="input" inputmode="numeric" maxlength="4" autocomplete="new-password"><p class="error-text" id="pin-error" role="status"></p></form>`,`<button class="primary-button" data-action="save-pin">Save demo PIN</button>`)}
function productDialog(){openDialog('Built to grow with you.',`<div class="product-preview-photo">${art('wealth')}</div><div class="spacer"></div><div class="eyebrow">THE NEXT CHAPTER · CONCEPT</div><h3>A relationship that goes further.</h3><p class="lead">A concept collection of portfolio insights, deeper privileges, and a community for independent professionals.</p><div class="callout purple">${icon('spark',20)}${state.waitlist?'You’re already on the demo interest list. No email has been sent.':'Try joining the interest list. This only updates your demo profile; it does not sign you up for any service.'}</div>`,`<button class="primary-button" data-action="join-list" ${state.waitlist?'disabled':''}>${state.waitlist?'Interest saved in demo':'Join demo interest list'}</button><button class="secondary-button" data-action="close">Back to products</button>`)}
