'save-pin':()=>{const pin=$('#pin-new').value,confirm=$('#pin-confirm').value;if(!/^\d{4}$/.test(pin)){$('#pin-error').textContent='Enter a four-digit made-up PIN.';return}if(pin!==confirm){$('#pin-error').textContent='The two PINs do not match.';return}state.pinSet=true;save();openDialog('Demo PIN updated',`<div class="success"><div class="success-icon">${icon('lock',29)}</div><h3>You’re all set.</h3><p>Your demo PIN passed validation and has been discarded. No PIN is stored or sent.</p></div>`,`<button class="primary-button" data-action="close">Done</button>`)},
